#include <bits/stdc++.h>using namespace std; int main() {    int t;    cin >> t;    while(t-- > 0){      int n, x;      cin >> n >> x;      int a[n];      for(int i=0; i<n; i++){        cin >> a[i];      }      int maxDis = a[0];      for(int i=1; i<n; i++){        maxDis = max(maxDis, a[i]-a[i-1]);      }      maxDis = max(maxDis, 2*(x-a[n-1]));      cout << maxDis << endl;          }      }